    recipeIngredients: [
      { name: 'Fried Chicken Sandwich', quantity: 'custom (g)', foodWord: 'FRIEDCHICKENSANDWICH', portionDesc: 'custom (g)', portionGrams: 100.0, isDish: true },
      { name: 'chicken breast', quantity: '4¼ oz', section: 'chicken', ndbNo: '5062', portionDesc: 'g', portionGrams: 120.5 },
      { name: 'all-purpose enriched unbleached white flour', quantity: '¼ cup', section: 'chicken', ndbNo: '20581', portionDesc: 'g', portionGrams: 31.25 },
      { name: 'large egg', quantity: '½ egg', section: 'chicken', ndbNo: '1123', portionDesc: 'g', portionGrams: 25.0 },
      { name: 'whole milk', quantity: '1½ tbsp', section: 'chicken', ndbNo: '1077', portionDesc: 'g', portionGrams: 22.5 },
      { name: 'olive oil', quantity: '1 tbsp olive oil (absorbed into crust)', section: 'chicken', ndbNo: '4053', portionDesc: 'g', portionGrams: 13.5 },
      { name: 'salt', quantity: '½ tsp', section: 'chicken', ndbNo: '2047', portionDesc: 'g', portionGrams: 3.0 },
      { name: 'ground black pepper', quantity: '¼ tsp', section: 'chicken', ndbNo: '2030', portionDesc: 'g', portionGrams: 0.575 },
      { name: 'garlic powder', quantity: '½ tsp', section: 'chicken', ndbNo: '2020', portionDesc: 'g', portionGrams: 1.55 },
      { name: 'paprika', quantity: '½ tsp', section: 'chicken', ndbNo: '2028', portionDesc: 'g', portionGrams: 1.15 },
      { name: 'hamburger bun', quantity: '1 bun', section: 'assembly', ndbNo: '18350', portionDesc: 'g', portionGrams: 44.0 },
      { name: 'iceberg lettuce', quantity: '1 large leaf (15g)', section: 'assembly', ndbNo: '11252', portionDesc: 'g', portionGrams: 15.0 },
      { name: 'tomato', quantity: '30g sliced', section: 'assembly', ndbNo: '11529', portionDesc: 'g', portionGrams: 30.0 },
      { name: 'dill pickle', quantity: '20g sliced', section: 'assembly', ndbNo: '11937', portionDesc: 'g', portionGrams: 20.0 },
      { name: 'mayonnaise', quantity: '2 tbsp', section: 'assembly', ndbNo: '4025', portionDesc: 'g', portionGrams: 27.6 }
    ],
    recipeInstructions: [
      'In a shallow bowl, whisk together the egg and milk. In a separate bowl, combine the flour, salt, pepper, garlic powder, and paprika.',
      'Dip the chicken breast in the egg wash, letting the excess drip off, then dredge thoroughly in the seasoned flour.',
      'Heat ½ inch of olive oil to 350°F in a deep skillet. Fry the chicken for 5–6 minutes per side until golden brown and cooked through (internal temperature 165°F). Transfer to a rack to drain.',
      'Spread mayonnaise on both buns, then layer the lettuce, sliced tomato, and sliced pickles on the bottom bun.',
      'Place the fried chicken on top of the toppings, close with the top bun, and serve.',
      '(Oil in the ingredient list reflects only the amount absorbed into the crust.)',
      '1 serving (332g): 757 cal | 39.7g protein | 42.8g fat | 51.5g carbs | 3.1g fiber | 6.1g sugar | 190.8g water'
    ],
