    recipeIngredients: [
      { name: 'Corn Dog', quantity: 'custom (g)', foodWord: 'CORNDOG', portionDesc: 'custom (g)', portionGrams: 100.0, isDish: true },
      { name: 'Beef frankfurter', quantity: '6 frankfurters (288g)', section: 'corn_dog', ndbNo: '7022', portionDesc: 'g', portionGrams: 288.0 },
      { name: 'yellow cornmeal', quantity: '¾ cup (103.5g)', section: 'corn_dog', ndbNo: '20022', portionDesc: 'g', portionGrams: 103.5 },
      { name: 'all-purpose enriched unbleached white flour', quantity: '¼ cup (31.25g)', section: 'corn_dog', ndbNo: '20581', portionDesc: 'g', portionGrams: 31.25 },
      { name: 'baking powder', quantity: '1 tsp (4.6g)', section: 'corn_dog', ndbNo: '18370', portionDesc: 'g', portionGrams: 4.6 },
      { name: 'sugar', quantity: '1 tbsp (12.6g)', section: 'corn_dog', ndbNo: '19335', portionDesc: 'g', portionGrams: 12.6 },
      { name: 'salt', quantity: '½ tsp (3g)', section: 'corn_dog', ndbNo: '2047', portionDesc: 'g', portionGrams: 3.0 },
      { name: 'large egg', quantity: '1 large egg (50g)', section: 'corn_dog', ndbNo: '1123', portionDesc: 'g', portionGrams: 50.0 },
      { name: 'whole milk', quantity: '½ cup (122g)', section: 'corn_dog', ndbNo: '1077', portionDesc: 'g', portionGrams: 122.0 },
      { name: 'olive oil', quantity: '6 tsp absorbed (27g)', section: 'corn_dog', ndbNo: '4053', portionDesc: 'g', portionGrams: 27.0 }
    ],
    recipeInstructions: [
      'Heat 3 to 4 inches of oil in a large deep pot to 375°F (190°C).',
      'In a bowl, whisk together the cornmeal, flour, baking powder, sugar, and salt. Add the egg and milk; stir until a thick, smooth batter forms. Pour batter into a glass taller than the frankfurter is long.',
      'Pat the frankfurters dry. Insert a wooden skewer into each frank. Dip each frank into the batter turning to coat. Raise and let excess drip off. Then carefully lower into the hot oil, releasing just before it is fully submerged.',
      'Fry 2 to 3 corn dogs at a time for 2 to 3 minutes, turning once, until deep golden brown all over.',
      'Lift out and drain on a paper towel-lined rack. Serve with mustard or ketchup for dipping.'
    ],
    sections: [
      { key: 'corn_dog', label: 'Corn Dog:', cookingMethod: '', yieldFactorWater: 0.85 }
    ],
