    recipeIngredients: [
      { name: 'Tomato Ketchup', quantity: 'custom (g)', foodWord: 'KETCHUP', portionDesc: 'custom (g)', portionGrams: 100.0, isDish: true },
      { name: 'fresh tomatoes', quantity: '5 to 6 cups chopped fresh tomatoes (or 1 can (28 oz) crushed)', section: 'sauce', ndbNo: '11529', portionDesc: 'g', portionGrams: 794.0 },
      { name: 'apple cider vinegar', quantity: '1/2 cup', section: 'sauce', ndbNo: '2048', portionDesc: 'g', portionGrams: 119.5 },
      { name: 'brown sugar', quantity: '1/4 cup packed', section: 'sauce', ndbNo: '19334', portionDesc: 'g', portionGrams: 55.0 },
      { name: 'salt', quantity: '1 tsp', section: 'sauce', ndbNo: '2047', portionDesc: 'g', portionGrams: 6.0 },
      { name: 'onion powder', quantity: '1/2 tsp', section: 'sauce', ndbNo: '2026', portionDesc: 'g', portionGrams: 1.2 },
      { name: 'garlic powder', quantity: '1/4 tsp', section: 'sauce', ndbNo: '2020', portionDesc: 'g', portionGrams: 0.775 },
      { name: 'allspice', quantity: '1/4 tsp', section: 'sauce', ndbNo: '2001', portionDesc: 'g', portionGrams: 0.475 },
      { name: 'ground cloves', quantity: '1/8 tsp', section: 'sauce', ndbNo: '2011', portionDesc: 'g', portionGrams: 0.2625 },
      { name: 'Celery seed', quantity: '1/8 tsp', section: 'sauce', ndbNo: '2007', portionDesc: 'g', portionGrams: 0.25 }
    ],
    recipeInstructions: [
      'Combine the chopped fresh tomatoes (or crushed canned tomatoes), apple cider vinegar, brown sugar, salt, onion powder, garlic powder, allspice, cloves, and celery seed in a medium saucepan.',
      'Bring to a boil over medium-high heat, stirring to dissolve the sugar.',
      'Reduce heat to medium-low and simmer uncovered, stirring occasionally, until the ketchup thickens and reduces by about half — approximately 45 to 60 minutes.',
      'The ketchup is ready when a spoon dragged across the bottom of the pan leaves a clear trail that holds for several seconds.',
      'Taste and adjust seasoning — add a pinch more salt or a splash more vinegar if needed.',
      'Let cool for 10 minutes, then blend until smooth with an immersion blender (or transfer to a blender in batches).',
      'Transfer to clean glass jars and refrigerate. The ketchup keeps for up to 3 weeks.'
    ],
    sections: [
      { key: 'sauce', label: 'Sauce:', cookingMethod: '', yieldFactorWater: 0.603 }
    ],
