    recipeIngredients: [
      { name: 'Russian Dressing', quantity: 'custom (g)', foodWord: 'RUSSIANDRESSING', portionDesc: 'custom (g)', portionGrams: 100.0, isDish: true },
      { name: 'Mayonnaise', quantity: '½ cup (8 tbsp, 120g)', section: 'mayonnaise', foodWord: 'MAYONNAISE', portionDesc: 'g', portionGrams: 120.0, isDish: true, componentRef: 'SAUCE_009' },
      { name: 'Chili Sauce', quantity: '3 tbsp (51g)', section: 'chili_sauce', foodWord: 'CHILISAUCE', portionDesc: 'g', portionGrams: 51.0, isDish: true, componentRef: 'SAUCE_012' },
      { name: 'prepared horseradish', quantity: '1 tbsp', section: 'seasoning', ndbNo: '2055', portionDesc: 'g', portionGrams: 15.0 },
      { name: 'Worcestershire sauce', quantity: '1 tsp', section: 'seasoning', ndbNo: '6971', portionDesc: 'g', portionGrams: 5.0 },
      { name: 'lemon juice', quantity: '1 tsp', section: 'seasoning', ndbNo: '9152', portionDesc: 'g', portionGrams: 5.0 }
    ],
    recipeInstructions: [
      'Prepare one full recipe of Mayonnaise (see instructions in the recipe: Mayonnaise) and one full recipe of Chili Sauce (see instructions in the recipe: Chili Sauce). Note: store-bought substitutes will have a different nutrient profile.',
      'Combine the prepared horseradish, Worcestershire sauce, and lemon juice in a medium bowl; stir briefly to blend.',
      'Add the 1/2 cup of Mayonnaise and fold in gently until the mixture is smooth and evenly incorporated.',
      'Add the 3 tbsp of Chili Sauce and stir until the dressing is uniformly red-orange with no streaks.',
      'Taste and adjust: add more horseradish for extra bite, a splash of lemon juice for brightness, or a small pinch of salt if needed.',
      'Cover tightly and refrigerate for at least 30 minutes before serving to allow the flavors to meld.',
      'Serve as a sandwich spread, salad dressing, or dipping sauce. Store covered in the refrigerator for up to 1 week; stir before each use.'
    ],
